import{_ as e,o as n,c as i,a2 as t}from"./chunks/framework.BXzK3EA4.js";const h=JSON.parse('{"title":"Localization & Internationalization (i18n)","description":"","frontmatter":{},"headers":[],"relativePath":"guide/localization.md","filePath":"guide/localization.md"}'),o={name:"guide/localization.md"};function l(r,a,s,c,u,g){return n(),i("div",null,[...a[0]||(a[0]=[t('<h1 id="localization-internationalization-i18n" tabindex="-1">Localization &amp; Internationalization (i18n) <a class="header-anchor" href="#localization-internationalization-i18n" aria-label="Permalink to &quot;Localization &amp; Internationalization (i18n)&quot;">​</a></h1><p>FOSSBilling is designed for a global market, supporting multiple languages, currencies, and regional formatting out of the box.</p><hr><h2 id="🌍-language-management" tabindex="-1">🌍 Language Management <a class="header-anchor" href="#🌍-language-management" aria-label="Permalink to &quot;🌍 Language Management&quot;">​</a></h2><p>The system automatically detects the client&#39;s browser language and presents the appropriate translation if available.</p><h3 id="supported-languages" tabindex="-1">Supported Languages <a class="header-anchor" href="#supported-languages" aria-label="Permalink to &quot;Supported Languages&quot;">​</a></h3><p>FOSSBilling currently includes translations for:</p><ul><li>English (US/UK)</li><li>Indonesian (Bahasa Indonesia)</li><li>German (Deutsch)</li><li>French (Français)</li><li>Spanish (Español)</li><li>Arabic (العربية) - Including full RTL support.</li></ul><hr><h2 id="💰-multi-currency-billing" tabindex="-1">💰 Multi-Currency Billing <a class="header-anchor" href="#💰-multi-currency-billing" aria-label="Permalink to &quot;💰 Multi-Currency Billing&quot;">​</a></h2><p>You can define multiple currencies in the Admin Portal under <strong>Settings &gt; Currencies</strong>.</p><h3 id="key-features" tabindex="-1">Key Features <a class="header-anchor" href="#key-features" aria-label="Permalink to &quot;Key Features&quot;">​</a></h3><ul><li><strong>Default Currency:</strong> The internal currency used for base calculations.</li><li><strong>Conversion Rates:</strong> Set manual rates or enable automatic updates via external providers.</li><li><strong>Format Precision:</strong> Configure how many decimal places to show for each currency (e.g., 0 for IDR, 2 for USD).</li></ul><hr><h2 id="📅-regional-formatting" tabindex="-1">📅 Regional Formatting <a class="header-anchor" href="#📅-regional-formatting" aria-label="Permalink to &quot;📅 Regional Formatting&quot;">​</a></h2><p>FOSSBilling respects regional differences in data display:</p><ul><li><strong>Date Formats:</strong> Choose between <code>YYYY-MM-DD</code>, <code>DD/MM/YYYY</code>, or <code>MM/DD/YYYY</code>.</li><li><strong>Time Zones:</strong> Set a global system timezone or allow clients to set their own.</li><li><strong>Number Formats:</strong> Correct handling of decimal and thousands separators based on locale.</li></ul><hr><h2 id="✍️-contributing-translations" tabindex="-1">✍️ Contributing Translations <a class="header-anchor" href="#✍️-contributing-translations" aria-label="Permalink to &quot;✍️ Contributing Translations&quot;">​</a></h2><p>Translation files are located in the <code>pkg/i18n/locales/</code> directory as JSON files. If you want to add a new language or improve an existing one:</p><ol><li>Copy the <code>en_US.json</code> file.</li><li>Rename it to your locale code (e.g., <code>pt_BR.json</code>).</li><li>Translate the string values.</li><li>Submit a Pull Request to our repository.</li></ol>',21)])])}const p=e(o,[["render",l]]);export{h as __pageData,p as default};
